Method.Implementation:
	#dim trs As %ResultSet.Static
	#dim tSC As %Status=$$$OK
	#dim tFileBuildComplete As %Boolean=0	
	#dim tFile As %File
	#dim recTypeValue,fieldIDValue,fieldValueValue,tRecord AS %String=""
	#dim FILEHEADERRECTYPE As %String = "1"
	#dim COBATCHHEADERRECORD As %String = "5"
	#dim ENTRYDETAILRECORD As %String = "6"
	#dim ADDENDARECORD As %String = "7"
	#dim COBATCHCONTROLRECORD As %String = "8"
	#dim FILECONTROLRECORD As %String = "9"
	#dim totalAmountCalcCredit,totalAmountCalcDebit,Index,rowNum=0
	#dim tCredit,tDebit=0
	#dim totalCalculatedListCredit,totalCalculatedListDebit,totalSentList As %ListOfDataTypes
	set totalCalculatedListCredit=##class(%ListOfDataTypes).%New()
	set totalCalculatedListDebit=##class(%ListOfDataTypes).%New()
	set totalSentList=##class(%ListOfDataTypes).%New()

	set debug=$g(^IHCDebugCode(..%ConfigName),1)
	$$$TRACE("Inside Process835RestultSet")


		set rowNum=pEftResultSet.Next(.sc)
		if ((rowNum=0) || $$$ISERR(sc)){
			set tSC=$$$ERROR("ITFSHKBEFT005","Error Reading Result set - step 1")
			quit
		}

		set:debug ^IHCDebugCode(..%ConfigName,"rowcount ")=pEftResultSet.RowCount
		//Build file Header Record
		$$$TRACE("Building File Header")
		set headerString=""
		do {
		  	set Val1=pEftResultSet.GetData(1)
		  	set Val2=pEftResultSet.GetData(2)
		  	set Val3=pEftResultSet.GetData(3)

		  	$$$LOGINFO("rowNum : "_rowNum_" Val1**** "_Val1_"Val2**** "_Val2_"Val3***** "_Val3)
		   	set rowNum=pEftResultSet.Next(.sc)
		  	if ((rowNum=0)||$$$ISERR(sc)){
			  		set tSC=$$$ERROR("ITFSHKBEFT005","Incomplete Result set received or Error processing Resultset in Building file Header loop.")
		  	}
		  	if (rowNum=3)
		  	{
			  	$$$TRACE("Reached 3 rows ")
			  	Quit
		  	}
		} while (rowNum'=0)
		quit:$$$ISERR(tSC)
		/*set tSC=tFile.WriteLine(headerString)
		if ('$$$ISOK(tSC)){
			set tSC=$$$ERROR("ITFSHKBEFT004","Error Writing Header record to file "__fileName)
			quit
		}
		// Build Batch level details
		set sumOfBatchTotalsDebit=0
		set sumOfBatchTotalsCredit=0
		do {
			set totalAmountCalcCredit=0
			set totalAmountCalcDebit=0
			// buid batch Header
			$$$TRACE("Building Batch Header Records") 
			set batchHeaderString=""
			do {
		  		set recTypeValue=pEftResultSet.GetData(1)
		  		if (recTypeValue'=COBATCHHEADERRECORD){
				  	quit
		  		}
		  		set fieldIDValue=pEftResultSet.GetData(2)
		  		set fieldValueValue=pEftResultSet.GetData(3)
		  		set batchHeaderString=batchHeaderString_fieldValueValue
				set rowNum=pEftResultSet.Next(.sc)
		  		if ((rowNum=0)||$$$ISERR(sc)){
			  		set tSC=$$$ERROR("ITFSHKBEFT005","Incomplete Result set received or Error processing Resultset in Building Batch Header loop.")
		  		}
			} while (rowNum'=0)
			quit:$$$ISERR(tSC)
			set tSC=tFile.WriteLine(batchHeaderString)
			if ('$$$ISOK(tSC)){
				set tSC=$$$ERROR("ITFSHKBEFT004","Error Writing batchHeaderString record to file "__fileName)
				quit
			}

			// build  Batch level details record
			$$$TRACE("Building detail Records") 
			set detailRecord=""
			do {
		  		set recTypeValue=pEftResultSet.GetData(1)
		  		if (recTypeValue'=ENTRYDETAILRECORD){
			  		if (detailRecord'=""){
				  		set tSC=tFile.WriteLine(detailRecord)
						if ($$$ISERR(tSC)){
								set tSC=$$$ERROR("ITFSHKBEFT004","Error Writing detailRecord record to file "__fileName)
						}
						set detailRecord=""
				  	}
					// Check if it is a Addenda Record
					set nextRecord=0
				  	if (recTypeValue=ADDENDARECORD){
					  	// build Addenda 
					  	set addendaString=""
					  	do {
						  	set recTypeValue=pEftResultSet.GetData(1)
						  	if (recTypeValue'=ADDENDARECORD){
							  	quit
						  	}
						  	set fieldValueValue=pEftResultSet.GetData(3)
		  					set addendaString=addendaString_fieldValueValue
		  					set rowNum=pEftResultSet.Next(.sc)
		  					if ((rowNum=0)||$$$ISERR(sc)){
			  					set tSC=$$$ERROR("ITFSHKBEFT005","Incomplete Result set received or Error processing Resultset in Addenda record loop.")
		  					}
						} while (rowNum'=0)
						quit:$$$ISERR(tSC)
						set tSC=tFile.WriteLine(addendaString)
						if ($$$ISERR(tSC)){
							set tSC=$$$ERROR("ITFSHKBEFT004","Error Writing detailRecord record to file "__fileName)
							quit
						}
						if (recTypeValue'=ENTRYDETAILRECORD){ quit} 
					}else{ quit}

		  		}
		  		set fieldIDValue=pEftResultSet.GetData(2)
		  		set fieldValueValue=pEftResultSet.GetData(3)
		  		set fieldValueValueTmp = fieldValueValue
		  		//Is this a debit or credit transaction
		  		if (fieldIDValue="2"){
			  		if ((fieldValueValue="22") || (fieldValueValue="23") || (fieldValueValue="32") || (fieldValueValue="33"))
                      {
                           set tCredit=1
                      }
                      else
                      {
                          set tDebit=1
                      }
		  		}
		  		//Total the amounts for the successful email
		  		if (fieldIDValue="6"){
			  		if (tCredit){
				  		set tmpAmount=$FNUMBER($ZSTRIP(fieldValueValue,"*PA"," "),"D","")
				  		set totalAmountCalcCredit=totalAmountCalcCredit+tmpAmount
			  		}
			  		if (tDebit){
				  		set tmpAmount=$FNUMBER($ZSTRIP(fieldValueValue,"*PA"," "),"D","")
				  		set totalAmountCalcDebit=totalAmountCalcDebit+tmpAmount
			  		}
		  		}
			  	set detailRecord=detailRecord_fieldValueValue
			  	set rowNum=pEftResultSet.Next(.sc)
		  		if ((rowNum=0)||$$$ISERR(sc)){
			  		set tSC=$$$ERROR("ITFSHKBEFT005","Incomplete Result set received or Error processing Resultset in Building Detail record loop.")
		  		}
			} while (rowNum'=0)
			quit:$$$ISERR(tSC)
			set:debug ^IHCDebugCode(..%ConfigName,"totalAmountCalcCredit")=totalAmountCalcCredit
			set:debug ^IHCDebugCode(..%ConfigName,"totalAmountCalcDebit")=totalAmountCalcDebit
			set:debug ^IHCDebugCode(..%ConfigName,"isDebit")=tDebit
			set:debug ^IHCDebugCode(..%ConfigName,"isCredit")=tCredit

			$$$TRACE("Write Batch Control Record")
			set batchControlString=""
			do {
		  		set recTypeValue=pEftResultSet.GetData(1)
		  		if (recTypeValue'=COBATCHCONTROLRECORD){
			  		if (recTypeValue=FILECONTROLRECORD){
				  		set tFileBuildComplete=1
			  		}
			  		quit
		  		}
		  		set fieldIDValue=pEftResultSet.GetData(2)
		  		set fieldValueValue=pEftResultSet.GetData(3)
		  		set batchControlString=batchControlString_fieldValueValue
		  		if (fieldIDValue="5") //Compare Total calculated amount to total debit amount (detail level accumalation to Batch control)
		  		{   
		  		    set totalAmountSent=$FNUMBER($ZSTRIP(fieldValueValue,"*PA"," "),"D","")
		  		    set sumOfBatchTotalsDebit = sumOfBatchTotalsDebit + totalAmountSent
			  		set:debug ^IHCDebugCode(..%ConfigName,"totalAmountCalcDebit and and control record ")=totalAmountCalcDebit_" "_totalAmountSent
					if ((tDebit)&&(totalAmountCalcDebit'=totalAmountSent)){
				  		$$$TRACE("Calculated Debit "_totalAmountCalcDebit_" Actual Debit "_totalAmountSent)
				  		set tSC=$$$ERROR("ITFSHKBEFT006","Calculated Debit amounts do not match the total for the file")
				  		quit
			  		}else {
				  	  do totalCalculatedListDebit.Insert(totalAmountCalcDebit)
                      if (totalAmountCalcDebit '= 0)
                      {
                           do totalSentList.Insert(totalAmountSent)
                      }
			  		}
		  		}
		  		if (fieldIDValue="6") //Compare Total calculated amount to total credit amount (detail level accumalation to Batch control)
		  		{
			  		set totalAmountSent=$FNUMBER($ZSTRIP(fieldValueValue,"*PA"," "),"D","")
			  		set sumOfBatchTotalsCredit = sumOfBatchTotalsCredit + totalAmountSent
			  		set:debug ^IHCDebugCode(..%ConfigName,"totalAmountCalcCredit and control record ")=totalAmountCalcCredit_" "_totalAmountSent
					if ((tCredit)&&(totalAmountCalcCredit'=totalAmountSent)){
				  		$$$TRACE("Calculated Credit "_totalAmountCalcCredit_" Actual Credit "_fieldValueValue)
				  		set tSC=$$$ERROR("ITFSHKBEFT007","Calculated Credit amounts do not match the total for the file")
			  		}else {
				  	  do totalCalculatedListCredit.Insert(totalAmountCalcCredit)
                      if (totalAmountCalcCredit '= 0)
                      {
                           do totalSentList.Insert(totalAmountSent)
                      }
			  		}
		  		}
		  		set rowNum=pEftResultSet.Next(.sc)
		  		if ((rowNum=0)||$$$ISERR(sc)){
			  		set tSC=$$$ERROR("ITFSHKBEFT005","Incomplete Result set received or Error processing Resultset in Building Batch control record loop.")
		  		}
			} while (rowNum'=0)
			quit:$$$ISERR(tSC)
			set tSC=tFile.WriteLine(batchControlString)
			if ('$$$ISOK(tSC)){
				set tSC=$$$ERROR("ITFSHKBEFT004","Error Writing batchControlString record to file "__fileName)
				quit
			}

		}while (tFileBuildComplete=0)

		if ($$$ISERR(tSC)){
			quit
		}
	  	//Build File Control

		$$$TRACE("Building File Control")
		set fileControlString=""
		do {
		  	set recTypeValue=pEftResultSet.GetData(1)
		  	set fieldIDValue=pEftResultSet.GetData(2)
		  	set fieldValueValue=pEftResultSet.GetData(3)
		  	set fileControlString=fileControlString_fieldValueValue
		  	if (fieldIDValue="6") //compare totaled batch Debit amount to the file debit amount
		  	{
			  	set totalFileControlDebit=$FNUMBER($ZSTRIP(fieldValueValue,"*PA"," "),"D","")
			  	$$$TRACE("Debug - Total Debit Amount for this file is: "_totalFileControlDebit_" Total sum of all Debits in batches is : "_sumOfBatchTotalsDebit)
			  	set:debug ^IHCDebugCode(..%ConfigName,"Calculated Batch Debit and total for the file")=sumOfBatchTotalsDebit_"    "_totalFileControlDebit
			  	if (totalFileControlDebit'=sumOfBatchTotalsDebit)
			  	{
				  	set tSC=$$$ERROR("ITFSHKBEFT008","Calculated Batch Debit amounts do not match the total for the file")
			  	}
		  	}
		  	if (fieldIDValue="7") //compare totaled batch Credit amount to the file credit amount
		  	{
			  	set totalFileControlCredit=$FNUMBER($ZSTRIP(fieldValueValue,"*PA"," "),"D","")
			  	$$$TRACE("Debug - Total Credit Amount for this file is: "_totalFileControlCredit_" Total sum of all Credit in batches is : "_sumOfBatchTotalsCredit)
			  	set:debug ^IHCDebugCode(..%ConfigName,"Calculated Batch Credit amount and Total for the file")=sumOfBatchTotalsCredit_"    "_totalFileControlCredit
			  	if (totalFileControlCredit'=sumOfBatchTotalsCredit)
			  	{
				  	set tSC=$$$ERROR("ITFSHKBEFT009","Calculated Batch Debit amounts do not match the total for the file")
			  	}
		  	}
		  	set rowNum=pEftResultSet.Next(.sc)
		} while (rowNum'=0)
		set tSC=tFile.WriteLine(fileControlString)
		if ('$$$ISOK(tSC)){
			set tSC=$$$ERROR("ITFSHKBEFT004","Error Writing Header record to file "__fileName)
			quit
		}
	  } while(0)

	  set pResponse=##class(IHC.ITF.Response.GenerateEftFileResponse).%New()  
	  if $$$ISERR(tSC){
		  do tFile.%Delete()
	      set pResponse.messageCode=$System.Status.GetErrorCodes(tSC)
	   	  set pResponse.messageDescription=$System.Status.GetOneErrorText(tSC) 
	   }
	   else{
		  set pResponse.messageCode=1
	   	  set pResponse.messageDescription="SUCCESS"
	   	  set pResponse.immediateDestination=immediateDestination
	   	  set pResponse.totalCalculatedListCredit=totalCalculatedListCredit
	   	  set pResponse.totalCalculatedListDebit=totalCalculatedListDebit
	   	  set pResponse.totalFileControlCredit=totalFileControlCredit
	   	  set pResponse.totalFileControlDebit=totalFileControlDebit
	   	  set pResponse.totalSentList=totalSentList
	   }*/


  	quit tSC
